,"labelAr":"توجد آلية تحدد متى ومن وكيف تتم المتابعة","sourceOptionValue":100,"anchorScore":100,"scoreMode":"DIRECT_ANCHOR","scoreEligible":true,"anchorMax":100}]},{"code":"Q22","axisCode":"A5","required":true,"questionTextAr":"إذا تغيب المريض عن موعده دون إشعار مسبق، ما الذي يحدث عادة؟","options":[{"index":0,"labelAr":"ننتظر أن يتواصل بنفسه","sourceOptionValue":0,"anchorScore":0,"scoreMode":"DIRECT_ANCHOR","scoreEligible":true,"anchorMax":100},{"index":1,"labelAr":"نتواصل لإعادة جدولة الموعد","sourceOptionValue":40,"anchorScore":40,"scoreMode":"DIRECT_ANCHOR","scoreEligible":true,"anchorMax":100},{"index":2,"labelAr":"نتواصل لمعرفة سبب عدم الحضور","sourceOptionValue":70,"anchorScore":70,"scoreMode":"DIRECT_ANCHOR","scoreEligible":true,"anchorMax":100},{"index":3,"labelAr":"نعرف السبب ونعمل على استكمال الرحلة وإعادة الجدولة","sourceOptionValue":100,"anchorScore":100,"scoreMode":"DIRECT_ANCHOR","scoreEligible":true,"anchorMax":100}]},{"code":"Q23","axisCode":"A5","required":true,"questionTextAr":"كيف يتم تحديد توقيت التواصل مع المريض ضمن رحلته؟","options":[{"index":0,"labelAr":"عند توفر الوقت أو تذكر الحاجة","sourceOptionValue":0,"anchorScore":0,"scoreMode":"DIRECT_ANCHOR","scoreEligible":true,"anchorMax":100},{"index":1,"labelAr":"بناءً على الحالة والمواعيد السابقة","sourceOptionValue":40,"anchorScore":40,"scoreMode":"DIRECT_ANCHOR","scoreEligible":true,"anchorMax":100},{"index":2,"labelAr":"بناءً على نقاط محددة في رحلة المريض","sourceOptionValue":70,"anchorScore":70,"scoreMode":"DIRECT_ANCHOR","scoreEligible":true,"anchorMax":100},{"index":3,"labelAr":"بناءً على نقاط واحتياجات واضحة مع مراعاة الوقت ووسيلة التواصل المناسبة للمريض","sourceOptionValue":100,"anchorScore":100,"scoreMode":"DIRECT_ANCHOR","scoreEligible":true,"anchorMax":100}]},{"code":"Q24","axisCode":"A5","required":true,"questionTextAr":"كيف يتم التعامل مع المرضى الذين انقطعوا عن زيارة العيادة لفترة طويلة؟","options":[{"index":0,"labelAr":"لا توجد آلية لإعادة التواصل","sourceOptionValue":0,"anchorScore":0,"scoreMode":"DIRECT_ANCHOR","scoreEligible":true,"anchorMax":100},{"index":1,"labelAr":"يتم إرسال رسائل أو عروض عامة","sourceOptionValue":40,"anchorScore":40,"scoreMode":"DIRECT_ANCHOR","scoreEligible":true,"anchorMax":100},{"index":2,"labelAr":"تتم مراجعة حالة المريض قبل إعادة التواصل","sourceOptionValue":70,"anchorScore":70,"scoreMode":"DIRECT_ANCHOR","scoreEligible":true,"anchorMax":100},{"index":3,"labelAr":"تتم إعادة التواصل بناءً على احتياج المريض ومرحلته العلاجية وتفضيلاته","sourceOptionValue":100,"anchorScore":100,"scoreMode":"DIRECT_ANCHOR","scoreEligible":true,"anchorMax":100}]},{"code":"Q25","axisCode":"A5","required":true,"questionTextAr":"كيف تقيس العيادة تجربة المرضى ورضاهم واستعدادهم للتوصية بها؟","options":[{"index":0,"labelAr":"نعتمد على الانطباعات العامة","sourceOptionValue":0,"anchorScore":0,"scoreMode":"DIRECT_ANCHOR","scoreEligible":true,"anchorMax":100},{"index":1,"labelAr":"نجمع التعليقات أو التقييمات","sourceOptionValue":40,"anchorScore":40,"scoreMode":"DIRECT_ANCHOR","scoreEligible":true,"anchorMax":100},{"index":2,"labelAr":"نستخدم أسئلة أو أدوات محددة للقياس","sourceOptionValue":70,"anchorScore":70,"scoreMode":"DIRECT_ANCHOR","scoreEligible":true,"anchorMax":100},{"index":3,"labelAr":"نستخدم قياساً منظماً ومنتظماً ونراجع نتائجه","sourceOptionValue":100,"anchorScore":100,"scoreMode":"DIRECT_ANCHOR","scoreEligible":true,"anchorMax":100}]}]'::jsonb) as x(code text,axisCode text,required boolean,questionTextAr text,options jsonb) loop
    select id into axis_id from wp08_patient_axis_map where code=q.axisCode;
    if axis_id is null then raise exception 'WP08 missing Patient Journey axis for %',q.code; end if;
    insert into public.questions(assessment_type_id,axis_id,code,question_text,question_text_ar,question_type,display_order,is_required,impact,layer,trap_for,status)
    values(new_type,axis_id,q.code,q.questionTextAr,q.questionTextAr,'select',substring(q.code from 2)::int,q.required,'medium',
      case when exists(select 1 from jsonb_array_elements(q.options) e where e->>'scoreMode'='SEMANTIC_ONLY') then 'SEMANTIC' else 'A' end,'[]'::jsonb,'active') returning id into question_id;
    for o in select * from jsonb_to_recordset(q.options) as z(index int,labelAr text,sourceOptionValue int,scoreMode text) loop
      insert into public.options(question_id,option_index,option_value,label,label_ar,display_text,display_text_ar,is_trap,display_order) values(question_id,o.index,o.sourceOptionValue,o.labelAr,o.labelAr,o.labelAr,o.labelAr,false,o.index);
    end loop;
  end loop;
  update public.assessment_families set current_published_version_id=new_type,updated_at=now() where id=family_id;
end $$;

